import { useState, useRef } from "react"
import { useForm } from "react-hook-form"
import { zodResolver } from "@hookform/resolvers/zod"
import { z } from "zod"
import { CheckCircle2, UploadCloud, X } from "lucide-react"
import { supabase } from "@/lib/supabase"
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogTrigger,
} from "@/components/ui/dialog"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"

const schema = z.object({
  email: z.string().email("Invalid email address"),
  notes: z.string().optional(),
})

type FormData = z.infer<typeof schema>

const ACCEPTED = ["application/pdf", "image/jpeg", "image/png", "image/webp"]
const MAX_SIZE = 10 * 1024 * 1024 // 10 MB

export function PaymentReceiptDialog({ children }: { children: React.ReactNode }) {
  const [open, setOpen] = useState(false)
  const [success, setSuccess] = useState(false)
  const [serverError, setServerError] = useState<string | null>(null)
  const [file, setFile] = useState<File | null>(null)
  const [fileError, setFileError] = useState<string | null>(null)
  const fileRef = useRef<HTMLInputElement>(null)

  const {
    register,
    handleSubmit,
    reset,
    formState: { errors, isSubmitting },
  } = useForm<FormData>({ resolver: zodResolver(schema) })

  const handleFile = (f: File | undefined) => {
    if (!f) return
    if (!ACCEPTED.includes(f.type)) {
      setFileError("Accepted formats: PDF, JPEG, PNG")
      return
    }
    if (f.size > MAX_SIZE) {
      setFileError("File must be under 10 MB")
      return
    }
    setFileError(null)
    setFile(f)
  }

  const onSubmit = async (data: FormData) => {
    setServerError(null)

    if (!file) {
      setFileError("Please upload your payment receipt.")
      return
    }

    // Check if user is registered
    const { data: reg, error: regError } = await supabase
      .from("registrations")
      .select("email")
      .eq("email", data.email)
      .single()

    if (regError || !reg) {
      setServerError("This email is not registered. Please register first before uploading a receipt.")
      return
    }

    const ext = file.name.split(".").pop()
    const path = `${Date.now()}-${data.email.replace(/[@.]/g, "_")}.${ext}`

    const { error: uploadErr } = await supabase.storage
      .from("payment-receipts")
      .upload(path, file)

    if (uploadErr) {
      setServerError("File upload failed. Please try again.")
      return
    }

    const { error } = await supabase.from("payment_receipts").insert([{
      email: data.email,
      file_path: path,
      notes: data.notes ?? "",
    }])

    if (error) {
      setServerError("Something went wrong. Please try again.")
      return
    }

    fetch("/api/send-email", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ type: "payment", email: data.email, notes: data.notes }),
    }).catch(() => {})

    setSuccess(true)
  }

  const handleOpenChange = (val: boolean) => {
    if (!val) { reset(); setSuccess(false); setServerError(null); setFile(null); setFileError(null) }
    setOpen(val)
  }

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogTrigger asChild>{children}</DialogTrigger>
      <DialogContent className="max-w-md">
        {success ? (
          <div className="py-10 text-center space-y-4">
            <CheckCircle2 className="h-14 w-14 text-green-500 mx-auto" />
            <DialogTitle>Receipt received!</DialogTitle>
            <p className="text-sm text-muted-foreground leading-relaxed">
              Your payment receipt (╬æ╧Ç╬┐╬┤╬╡╬╣╬║╧ä╬╣╬║╧î ╬á╬╗╬╖╧ü╧ë╬╝╬«╧é) has been uploaded successfully.
              We will confirm your payment within a few business days.
            </p>
            <Button onClick={() => handleOpenChange(false)}>Close</Button>
          </div>
        ) : (
          <>
            <DialogHeader>
              <DialogTitle>Upload Payment Receipt</DialogTitle>
              <DialogDescription>
                ╬æ╧Ç╬┐╬┤╬╡╬╣╬║╧ä╬╣╬║╧î ╬á╬╗╬╖╧ü╧ë╬╝╬«╧é ┬╖ PDF or image ┬╖ max 10 MB
              </DialogDescription>
            </DialogHeader>

            <form onSubmit={handleSubmit(onSubmit)} className="space-y-4 mt-1">
              <div className="space-y-1.5">
                <Label htmlFor="pay-email">Registration Email *</Label>
                <Input
                  id="pay-email"
                  type="email"
                  placeholder="Use the email you registered with"
                  {...register("email")}
                  aria-invalid={!!errors.email}
                />
                {errors.email && <p className="text-xs text-destructive">{errors.email.message}</p>}
              </div>

              <div className="space-y-1.5">
                <Label>Payment Receipt *</Label>
                {file ? (
                  <div className="flex items-center gap-2 p-2 border rounded-md text-sm">
                    <span className="flex-1 truncate text-foreground">{file.name}</span>
                    <button
                      type="button"
                      onClick={() => { setFile(null); setFileError(null); if (fileRef.current) fileRef.current.value = "" }}
                      className="text-muted-foreground hover:text-foreground transition-colors cursor-pointer"
                    >
                      <X className="h-4 w-4" />
                    </button>
                  </div>
                ) : (
                  <label className="flex flex-col items-center justify-center gap-2 border-2 border-dashed rounded-md p-6 text-sm text-muted-foreground cursor-pointer hover:border-primary/50 hover:bg-muted/30 transition-colors">
                    <UploadCloud className="h-6 w-6" />
                    <span>Click to select file</span>
                    <span className="text-xs">PDF, JPEG, PNG ΓÇö max 10 MB</span>
                    <input
                      ref={fileRef}
                      type="file"
                      accept=".pdf,.jpg,.jpeg,.png,.webp"
                      className="sr-only"
                      onChange={(e) => handleFile(e.target.files?.[0])}
                    />
                  </label>
                )}
                {fileError && <p className="text-xs text-destructive">{fileError}</p>}
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="pay-notes">
                  Notes{" "}
                  <span className="text-muted-foreground font-normal">(optional)</span>
                </Label>
                <Textarea
                  id="pay-notes"
                  rows={2}
                  placeholder="e.g. transfer reference number"
                  {...register("notes")}
                />
              </div>

              {serverError && (
                <p className="text-sm text-destructive bg-destructive/10 border border-destructive/30 rounded-md px-3 py-2">
                  {serverError}
                </p>
              )}

              <Button type="submit" className="w-full" disabled={isSubmitting}>
                {isSubmitting ? "UploadingΓÇª" : "Upload Receipt"}
              </Button>
            </form>
          </>
        )}
      </DialogContent>
    </Dialog>
  )
}

import { useState, useEffect, useCallback } from "react"

const navItems = [
  { href: "#program", label: "Program" },
  { href: "#labs", label: "Labs" },
  { href: "#field-trip", label: "Field Trip" },
  { href: "#registration", label: "Registration" },
  { href: "#travel", label: "Travel & Accommodation" },
  { href: "#committees", label: "Organizers" },
  { href: "#contact", label: "Contact" },
]

function useActiveSection() {
  const [active, setActive] = useState("")

  useEffect(() => {
    const ids = navItems.map((i) => i.href.slice(1))
    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            setActive(entry.target.id)
          }
        }
      },
      { rootMargin: "-30% 0px -65% 0px" }
    )
    for (const id of ids) {
      const el = document.getElementById(id)
      if (el) observer.observe(el)
    }
    return () => observer.disconnect()
  }, [])

  return active
}

function useScrolled() {
  const [scrolled, setScrolled] = useState(false)
  const onScroll = useCallback(() => setScrolled(window.scrollY > 20), [])
  useEffect(() => {
    window.addEventListener("scroll", onScroll, { passive: true })
    onScroll()
    return () => window.removeEventListener("scroll", onScroll)
  }, [onScroll])
  return scrolled
}

export function Navigation() {
  const [isOpen, setIsOpen] = useState(false)
  const activeSection = useActiveSection()
  const scrolled = useScrolled()

  return (
    <nav
      className="sticky top-0 z-50 w-full bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/60"
      style={{
        borderBottom: scrolled ? "1px solid var(--border)" : "1px solid transparent",
        boxShadow: scrolled ? "0 1px 12px rgba(0,0,0,0.06)" : "none",
        transition: "box-shadow 0.4s ease, border-color 0.4s ease",
      }}
    >
      <div className="container flex h-16 items-center justify-between">
        {/* Brand */}
        <a href="#" className="flex items-center gap-3 cursor-pointer group">
          <img
            src={`${import.meta.env.BASE_URL}images/logo-denuchange.jpg`}
            alt="DENUCHANGE"
            className="h-9 w-9 rounded-full object-cover ring-2 ring-primary/20 group-hover:ring-primary/40 transition-all"
            width={36}
            height={36}
          />
          <div className="flex flex-col leading-none">
            <span
              className="text-sm font-bold tracking-tight"
              style={{ fontFamily: "'Plus Jakarta Sans', 'Inter', system-ui, sans-serif" }}
            >
              DENUCHANGE
            </span>
            <span className="text-[10px] font-medium text-muted-foreground tracking-widest uppercase">
              Workshop 2026
            </span>
          </div>
        </a>

        {/* Desktop links */}
        <div className="hidden md:flex items-center gap-1">
          {navItems.map((item) => {
            const isActive = activeSection === item.href.slice(1)
            return (
              <a
                key={item.href}
                href={item.href}
                className={`relative px-3 py-2 text-[13px] font-semibold uppercase tracking-wide transition-colors duration-300 cursor-pointer rounded-md ${
                  isActive
                    ? "text-primary"
                    : "text-foreground/60 hover:text-foreground hover:bg-muted/50"
                }`}
              >
                {item.label}
                <span
                  className="absolute bottom-0.5 left-3 right-3 h-[2px] bg-primary rounded-full"
                  style={{
                    transform: isActive ? "scaleX(1)" : "scaleX(0)",
                    transition: "transform 0.3s cubic-bezier(0.22,1,0.36,1)",
                    transformOrigin: "center",
                  }}
                />
              </a>
            )
          })}
        </div>

        {/* Mobile menu button */}
        <button
          className="md:hidden p-2 cursor-pointer"
          onClick={() => setIsOpen(!isOpen)}
          aria-label="Toggle menu"
        >
          <svg
            className="h-5 w-5"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            {isOpen ? (
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M6 18L18 6M6 6l12 12"
              />
            ) : (
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M4 6h16M4 12h16M4 18h16"
              />
            )}
          </svg>
        </button>
      </div>

      {/* Mobile menu dropdown */}
      <div
        className="md:hidden border-t bg-background overflow-hidden"
        style={{
          maxHeight: isOpen ? "400px" : "0",
          opacity: isOpen ? 1 : 0,
          transition: "max-height 0.35s cubic-bezier(0.22,1,0.36,1), opacity 0.25s ease",
        }}
      >
        <div className="container py-3 flex flex-col gap-0.5">
          {navItems.map((item) => {
            const isActive = activeSection === item.href.slice(1)
            return (
              <a
                key={item.href}
                href={item.href}
                onClick={() => setIsOpen(false)}
                className={`text-[13px] font-semibold uppercase tracking-wide py-2.5 px-3 rounded-md transition-colors cursor-pointer ${
                  isActive
                    ? "text-primary bg-primary/5"
                    : "text-foreground/70 hover:text-foreground hover:bg-muted"
                }`}
              >
                {item.label}
              </a>
            )
          })}
        </div>
      </div>
    </nav>
  )
}

import { createContext, useContext, type ReactNode } from "react"

type Theme = "light" | "dark" | "system"

type ThemeProviderContextType = {
  theme: Theme
  resolvedTheme: "light" | "dark"
  setTheme: (theme: Theme) => void
}

const ThemeProviderContext = createContext<ThemeProviderContextType>({
  theme: "light",
  resolvedTheme: "light",
  setTheme: () => {},
})

export function ThemeProvider({ children }: { children: ReactNode }) {
  // Simple light-only theme for this workshop site
  return (
    <ThemeProviderContext.Provider
      value={{
        theme: "light",
        resolvedTheme: "light",
        setTheme: () => {},
      }}
    >
      {children}
    </ThemeProviderContext.Provider>
  )
}

export function useTheme() {
  return useContext(ThemeProviderContext)
}

